```js
// Returns an array of broken bricks after resolving ball/brick collisions,
// flipping the ball's velocity once per frame (per-face) and pushing it out of
// the bricks so it never sticks.
export function brickHit(ball, bricks) {
  let bounced = false;
  const broken = [];
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    brick.alive = false;
    broken.push(brick);
    if (!bounced) {
      bounceBall(ball, brick);
      bounced = true;
    }
  }
  return broken;
}

function bounceBall(ball, brick) {
  const overlapLeft = ball.x + ball.r - brick.x;
  const overlapRight = brick.x + brick.w - (ball.x - ball.r);
  const overlapTop = ball.y + ball.r - brick.y;
  const overlapBottom = brick.y + brick.h - (ball.y - ball.r);
  const minX = Math.min(overlapLeft, overlapRight);
  const minY = Math.min(overlapTop, overlapBottom);

  if (minX < minY) {
    // Hit a left/right face: flip horizontal velocity.
    ball.vx = -ball.vx;
    if (overlapLeft < overlapRight) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
  } else if (minY < minX) {
    // Hit a top/bottom face: flip vertical velocity.
    ball.vy = -ball.vy;
    if (overlapTop < overlapBottom) ball.y = brick.y - ball.r;
    else ball.y = brick.y + brick.h + ball.r;
  } else {
    // Corner/edge equal penetration: flip both.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
