export function brickHit(ball, bricks) {
  const prevX = ball.prevX ?? ball.x;
  const prevY = ball.prevY ?? ball.y;
  // Number of sweep samples scaled by travel distance, so fast/tunnelling moves
  // are sampled finely enough to never skip a brick.
