    if (!brick.alive) continue;
    let hit = false;
    if (collides(ball, brick)) {
      hit = true;
    } else {
      // sweep: check overlap along the travelled path
      for (let i = 1; i <= samples; i++) {
        const t = i / samples;
        const sx = prevX + (ball.x - prevX) * t;
        const sy = prevY + (ball.y - prevY) * t;
        if (collides({ x: sx, y: sy, r: ball.r }, brick)) { hit = true; break; }
      }
    }
    if (!hit) continue;
    brick.alive = false;
    broken.push(brick);
    if (!bounced) {
      bounceBall(ball, prevX, prevY, brick);
      bounced = true;
    }
  }
